21	/**
22	 * OpenCode SDK Provider
23	 *
24	 * This provider requires the @opencode-ai/sdk package, which is not installed by default.
25	 * Users must install it separately:
26	 *   npm install @opencode-ai/sdk
27	 *
28	 * OpenCode is an open-source AI coding agent for the terminal with support for 75+ LLM providers.
29	 *
30	 * Key features:
31	 * - Client-server architecture with local server management
32	 * - Support for 75+ LLM providers (Anthropic, OpenAI, Google, Ollama, etc.)
33	 * - Built-in tools (bash, read, write, edit, grep, glob, etc.)
34	 * - Session-based conversations with persistence
35	 * - MCP server integration
36	 * - Custom agent definitions
37	 *
38	 * Default configurations:
39	 * - No working_dir: Runs in temp directory with no tools (chat-only mode)
40	 * - With working_dir: Runs in specified directory with read-only tools (read, grep, glob, list)
41	 *
42	 * For side effects (file writes, bash commands), configure tools and permissions explicitly.
43	 */
44	
45	// Default read-only tools when working_dir is specified (alphabetically sorted)
46	export const FS_READONLY_TOOLS = ['glob', 'grep', 'list', 'read'];
47	
48	/**
49	 * Tool configuration for OpenCode SDK
50	 */
51	export interface OpenCodeToolConfig {
52	  bash?: boolean;
53	  edit?: boolean;
54	  write?: boolean;
55	  read?: boolean;
56	  grep?: boolean;
57	  glob?: boolean;
58	  list?: boolean;
59	  patch?: boolean;
60	  todowrite?: boolean;
61	  todoread?: boolean;
62	  webfetch?: boolean;
63	  /** Prompt user for input during execution */
64	  question?: boolean;
65	  /** Load SKILL.md files into conversation */
66	  skill?: boolean;
67	  /** Code intelligence queries (experimental - requires OPENCODE_EXPERIMENTAL_LSP_TOOL=true) */
68	  lsp?: boolean;
69	  [key: string]: boolean | undefined; // MCP tools: mcp_*
70	}
71	
72	/**
73	 * Permission value type - simple or pattern-based
74	 * Pattern-based permissions use glob patterns as keys (e.g., "*.ts": "allow")
75	 */
76	export type OpenCodePermissionValue =
77	  | 'ask'
78	  | 'allow'
79	  | 'deny'
80	  | Record<string, 'ask' | 'allow' | 'deny'>;
81	
82	/**
83	 * Permission configuration for specific tools
84	 *
85	 * Supports both simple values ('ask', 'allow', 'deny') and pattern-based
86	 * configuration using glob patterns for granular control.
87	 *
88	 * @example
89	 * ```yaml
90	 * permission:
91	 *   bash: allow  # Simple: allow all bash commands
92	 *   edit:
93	 *     "*.md": allow      # Pattern: allow editing markdown files
94	 *     "src/**": ask      # Pattern: ask for src directory
95	 *   external_directory: deny  # Deny access outside working dir
96	 * ```
97	 */
98	export interface OpenCodePermissionConfig {
99	  /** Shell command execution permission */
100	  bash?: OpenCodePermissionValue;
101	  /** File editing permission */
102	  edit?: OpenCodePermissionValue;
103	  /** Web fetching permission */
104	  webfetch?: OpenCodePermissionValue;
105	  /** Prevents infinite agent loops (added in v1.1.1) */
106	  doom_loop?: OpenCodePermissionValue;
107	  /** Access to directories outside the working directory (added in v1.1.1) */
108	  external_directory?: OpenCodePermissionValue;
109	}
110	
111	/**
112	 * Custom agent configuration
113	 *
114	 * Defines a specialized agent with specific capabilities, model settings,
115	 * and tool access controls.
116	 */
117	export interface OpenCodeAgentConfig {
118	  /** Required description explaining the agent's purpose */
119	  description: string;
120	  /** Agent mode: 'primary' for main assistants, 'subagent' for specialized tasks, 'all' for both */
121	  mode?: 'primary' | 'subagent' | 'all';
122	  /** Model ID to use for this agent (overrides global model) */
123	  model?: string;
124	  /** Temperature for response randomness (0.0-1.0) */
125	  temperature?: number;
126	  /** Nucleus sampling parameter (0.0-1.0) */
127	  top_p?: number;
128	  /** Tool configuration for this agent */
129	  tools?: OpenCodeToolConfig;
130	  /** Permission configuration for this agent */
131	  permission?: OpenCodePermissionConfig;
132	  /** Custom system prompt for the agent */
133	  prompt?: string;
134	  /**
135	   * Maximum agentic iterations before forcing text-only response
136	   * @deprecated Use `steps` instead (deprecated in v1.1.1)
137	   */
138	  maxSteps?: number;
139	  /** Maximum agentic iterations before forcing text-only response (replaces maxSteps) */
140	  steps?: number;
141	  /** Hex color code for visual identification (e.g., "#ff5500") */
142	  color?: string;
143	  /** Disable this agent */
144	  disable?: boolean;
145	  /** Hide this agent from @ autocomplete (subagents only) */
146	  hidden?: boolean;
147	}
148	
149	/**
150	 * MCP local server configuration
151	 */
152	export interface OpenCodeMCPLocalConfig {
153	  type: 'local';
154	  command: string[];
155	  environment?: Record<string, string>;
156	  enabled?: boolean;
157	  timeout?: number;
158	}
159	
160	/**
161	 * OAuth configuration for MCP remote servers
162	 */
163	export interface OpenCodeMCPOAuthConfig {
164	  /** OAuth client ID */
165	  clientId: string;
166	  /** OAuth client secret */
167	  clientSecret?: string;
168	  /** OAuth scope(s) to request */
169	  scope?: string;
170	}
171	
172	/**
173	 * MCP remote server configuration
174	 */
175	export interface OpenCodeMCPRemoteConfig {
176	  type: 'remote';
177	  url: string;
178	  headers?: Record<string, string>;
179	  /** OAuth configuration for authenticated MCP servers */
180	  oauth?: OpenCodeMCPOAuthConfig;
181	  enabled?: boolean;
182	  timeout?: number;
183	}
184	
185	/**
186	 * MCP server configuration (local or remote)
187	 */
188	export type OpenCodeMCPServerConfig = OpenCodeMCPLocalConfig | OpenCodeMCPRemoteConfig;
189	
